--
-- Pulkit's Hyprland config (Lua, Hyprland 0.56+).
-- This file and conf/ are symlinks into the dotfiles repo (GNU Stow);
-- themes/theme.lua and themes/colors.lua are generated by HyDE and are not.
--
-- Order matters: later files override earlier ones (userprefs.lua last).

require("conf.monitors")
require("conf.autostart")
require("conf.env")
require("conf.input")
require("conf.general")

require("conf.animations")
require("conf.keybindings")
require("conf.windowrules")
require("conf.scratchpads")
require("conf.gamemode").setup_auto() -- auto gamemode for fullscreen games

-- Theme: themes/common.lua + themes/theme.lua + themes/colors.lua (all plain data).
-- HYDE is global so scripts can reach it later through `hyprctl eval`
-- (swwwallbash.sh calls HYDE.reload_colors() after a wallpaper change).
HYDE = require("conf.theme")
HYDE.apply()

require("conf.userprefs")
